INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('mbe_995', 'mbe', '995', '746', '1992', '', '485', '', 'An issue in Parker''s action against Daves for causing Parker''s back injury was whether Parker''s condition had resulted principally from a similar occurrence five years before, with which Daves had no connection. Parker called Watts, his treating physician, who offered to testify that when she saw Parker after the latest occurrence, Parker told her that before the accident he had been working full time, without pain or limitation of motion, in a job that involved lifting heavy boxes. Watts''s testimony should be', 'admitted, because it is a statement of Parker''s then existing physical condition.', 'admitted, because it is a statement made for purposes of medical diagnosis or treatment.', 'excluded, because it is hearsay, not within any exception.', 'excluded, because Parker is available as a witness.', 'B', 'A declarant’s statement about past or current causes, symptoms, or conditions, when made for the purpose of medical diagnosis or treatment, is not barred by the hearsay rules.', 'mbe_2703', 0, '485'),
('mbe_1010', 'mbe', '1010', '761', '1998', 'CRIM. LAW', '15', '', 'Joe and Marty were coworkers. Joe admired Marty''s wristwatch and frequently said how much he wished he had one like it. Marty decided to give Joe the watch for his birthday the following week. On the weekend before Joe''s birthday, Joe and Marty attended a company picnic. Marty took his watch off and left it on a blanket when he went off to join in a touch football game. Joe strolled by, saw the watch on the blanket, and decided to steal it. He bent over and picked up the watch. Before he could pocket it, however, Marty returned. When he saw Joe holding the watch, he said, "Joe, I know how much you like that watch. I was planning to give it to you for your birthday. Go ahead and take it now." Joe kept the watch. Joe has committed', 'larceny.', 'attempted larceny.', 'embezzlement.', 'no crime.', 'A', 'Larceny is a common law crime and is defined as “the wrongful or fraudulent taking of another''s property without his permission and with the intent to permanently deprive the owner of that property.” Britt v. Commonwealth, 276 Va. 569, 574, 667 S.E.2d 763, 765 (2008). Grand larceny is a form of larceny that “includes **332 the taking, not from the person of another, of goods having a value of $200 or more.” Id. (citing Code § 18.2–95).', 'mbe_2704', 0, '15'),
('mbe_1032', 'mbe', '1032', '782', '1998', 'CONTRACTS', '37', 'Buyer, Inc., contracted in writing with Shareholder, who owned all of XYZ Corporation''s outstanding stock, to purchase all of her stock at a specified price per share. At the time this contract was executed, Buyer''s contracting officer said to Shareholder, "Of course, our commitment to buy is conditioned on our obtaining approval of the contract from Conglomerate, Ltd., our parent company." Shareholder replied, "Fine. No problem."', 'For this question only, assume that Conglomerate orally approved the contract, but that Shareholder changed her mind and refused to consummate the sale on two grounds: (1) when the agreement was made there was no consideration for her promise to sell; and (2) Conglomerate''s approval of the contract was invalid. If Buyer sues Shareholder for breach of contract, is Buyer likely to prevail?', 'Yes, because Buyer''s promise to buy, bargained for and made in exchange for Shareholder''s promise to sell, was good consideration even though it was expressly conditioned on an event that was not certain to occur.', 'Yes, because any possible lack of consideration for Shareholder''s promise to sell was expressly waived by Shareholder when the agreement was made.', 'No, because mutuality of obligation between the parties was lacking when the agreement was made.', 'No, because the condition of Conglomerate''s approval of the contract was an essential part of the agreed exchange and was not in a signed writing.', 'A', 'The concept of mutuality of obligation requires that both parties to a contract be bound by the terms of the contract. See, e.g., Floss, 211 F.3d at 315–16. It goes hand in hand with the concepts of “consideration” and the “illusory promise” (which is basically an empty promise: promising to do one thing while, at the same time, expressly retaining the right to change one''s mind). See id. at 316; 1 Samuel Williston, Contracts § 43, at 140 (3d ed.1957); 2 Arthur L. Corbin, Corbin on Contracts § 6.1 (Joseph M. Perillo, et al., eds., rev. ed.1995). Discussion of mutuality of obligations generally only arises in the context of a bilateral contract, where two parties bind themselves to an agreement by each promising to do one thing in exchange for the other''s promise to do another thing. See Helle v. Landmark, Inc., 15 Ohio App.3d 1, 472 N.E.2d 765, 776 (1984) (“Stripped to its essence, the concept of ‘mutuality of obligation’ expresses the idea that ‘both parties to the contract must be bound or neither is bound.’ However, this formulation applies only to an analysis of bilateral contracts, in which reciprocal promises are exchanged.”);  Corbin on Contracts, supra, § 6.1, at 203–04. Thus, to say a contract lacks mutuality of obligation is to say only that one party has failed to actually promise to do the thing he said he would do, or, stated yet a third way, has failed to give consideration.', 'mbe_2705', 0, '37'),
('mbe_1033', 'mbe', '1033', '782', '1998', 'CONTRACTS', '38', 'Buyer, Inc., contracted in writing with Shareholder, who owned all of XYZ Corporation''s outstanding stock, to purchase all of her stock at a specified price per share. At the time this contract was executed, Buyer''s contracting officer said to Shareholder, "Of course, our commitment to buy is conditioned on our obtaining approval of the contract from Conglomerate, Ltd., our parent company." Shareholder replied, "Fine. No problem."', 'For this question only, assume the following facts. Shareholder subsequently refused to consummate the sale on the ground that Buyer had neglected to request Conglomerate''s approval of the contract, which was true. Conglomerate''s chief executive officer, however, is prepared to testify that Conglomerate would have routinely approved the contract if requested to do so. Buyer can also prove that it has made a substantial sale of other assets to finance the stock purchase, although it admittedly had not anticipated any such necessity when it entered into the stock purchase agreement. If Buyer sues Shareholder for breach of contract, is Buyer likely to prevail?', 'Yes, because the condition of Conglomerate''s approval of the contract, being designed to protect only Buyer and Conglomerate, can be and has been waived by those entities.', 'Yes, because Buyer detrimentally relied on Shareholder''s commitment by selling off other assets to finance the stock purchase.', 'No, because the express condition of Conglomerate''s approval had not occurred prior to the lawsuit.', 'No, because obtaining Conglomerate''s approval of the contract was an event within Buyer''s control and Buyer''s failure to obtain it was itself a material breach of contract.', 'A', 'Thus, in order to successfully assert a claim for detrimental reliance, a plaintiff must establish: “(1) a representation by conduct or word; (2) justifiable reliance; and (3) a change in position to one''s detriment because of the reliance.” **11 Luther v. IOM Co. LLC, 13–353, pp. 10–11 (La.10/15/13), 130 So.3d 817, 825. However, detrimental reliance is not favored in Louisiana, and the failure of the plaintiff to prove each element will bar recovery. Id.', 'mbe_2706', 0, '38'),
('mbe_1038', 'mbe', '1038', '786', '1998', 'CONST. LAW', '43', '', 'City enacted an ordinance banning from its public sidewalks all machines dispensing publications consisting wholly of commercial advertisements. The ordinance was enacted because of a concern about the adverse aesthetic effects of litter from publications distributed on the public sidewalks and streets. However, City continued to allow machines dispensing other types of publications on the public sidewalks. As a result of the City ordinance, 30 of the 300 sidewalk machines that were dispensing publications in City were removed. Is this City ordinance constitutional?', 'Yes, because regulations of commercial speech are subject only to the requirement that they be rationally related to a legitimate state goal, and that requirement is satisfied here.', 'Yes, because City has a compelling interest in protecting the aesthetics of its sidewalks and streets, and such a ban is necessary to vindicate this interest.', 'No, because it does not constitute the least restrictive means with which to protect the aesthetics of City''s sidewalks and streets.', 'No, because there is not a reasonable fit between the legitimate interest of City in preserving the aesthetics of its sidewalks and streets and the means it chose to advance that interest.', 'D', 'If the communication is neither misleading nor related to unlawful activity, the government''s power is more circumscribed. The State must assert a substantial interest to be achieved by restrictions on commercial speech. Moreover, the regulatory technique must be in proportion to that interest. The limitation on expression must be designed carefully to achieve the State''s goal. Compliance with this requirement may be measured by two criteria. First, the restriction must directly advance the state interest involved; the regulation may not be sustained if it provides only ineffective or remote support for the government''s purpose. Second, if the governmental interest could be served as well by a more limited restriction on commercial speech, the excessive restrictions cannot survive.', 'mbe_2707', 0, '43'),
('mbe_1041', 'mbe', '1041', '789', '1998', 'CONST. LAW', '46', '', 'The state of Brunswick enacted a statute providing for the closure of the official state records of arrest and prosecution of all persons acquitted of a crime by a court or against whom criminal charges were filed and subsequently dropped or dismissed. The purpose of this statute is to protect these persons from further publicity or embarrassment relating to those state proceedings. However, this statute does not prohibit the publication of such information that is in the possession of private persons. A prominent businessman in Neosho City in Brunswick was arrested and charged with rape. Prior to trial, the prosecutor announced that new information indicated that the charges should be dropped. He then dropped the charges without further explanation, and the records relating thereto were closed to the public pursuant to the Brunswick statute. The Neosho City Times conducted an investigation to determine why the businessman was not prosecuted, but was refused access to the closed official state records. In an effort to determine whether the law enforcement agencies involved were properly doing their duty, the Times filed suit against appropriate state officials to force opening of the records and to invalidate the statute on constitutional grounds. Which of the following would be most helpful to the state in defending the constitutionality of this statute?', 'The fact that the statute treats in an identical manner the arrest and prosecution records of all persons who have been acquitted of a crime by a court or against whom criminal charges were filed and subsequently dropped or dismissed.', 'The argument that the rights of the press are no greater than those of citizens generally.', 'The fact that the statute only prohibits public access to these official state records and does not prohibit the publication of information they contain that is in the possession of private persons.', 'The argument that the state may seal official records owned by the state on any basis its legislature chooses.', 'C', '[W]e have held that the right to publish is central to the First Amendment and basic to the existence of constitutional democracy. Grosjean, supra, at 250, 56 S.Ct. at 449; New York Times, supra, 376 U.S. at 270, 84 S.Ct. at 720.
 
A corollary of the right to publish must be the right to gather news. The full flow of information to the public protected by the free-press guarantee would be severely curtailed if no protection whatever were afforded to the process by which news is assembled and disseminated. We have, therefore, recognized that there is a right to publish without prior governmental approval, Near v. Minnesota, 283 U.S. 697, 51 S.Ct. 625, 75 L.Ed. 1357; New York Times Co. v. United States, 403 U.S. 713, 91 S.Ct. 2140, 29 L.Ed.2d 822, a right to distribute information, see, e.g., Lovell v. Griffin, 303 U.S., 444, 452, 58 S.Ct. 666, 669, 82 L.Ed. 949; Marsh v. Alabama, 326 U.S. 501, 66 S.Ct. 276, 90 L.Ed. 265; Martin v. City of Struthers, 319 U.S. 141, 63 S.Ct. 862, 87 L.Ed. 1313; Grosjean, supra, and a right to receive printed matter, Lamont v. Postmaster General, 381 U.S. 301, 85 S.Ct. 1493, 14 L.Ed.2d 398.', 'mbe_2708', 0, '46'),
('mbe_1042', 'mbe', '1042', '790', '1998', 'CRIM. LAW', '47', '', 'Nora, executive director of an equal housing opportunity organization, was the leader of a sit-in at the offices of a real estate management company. The protest was designed to call attention to the company''s racially discriminatory rental practices. When police demanded that Nora desist from trespassing on the company''s property, she refused and was arrested. In Nora''s trial for trespass, the prosecution peremptorily excused all nonwhites from the jury, arguing to the court that even though Nora was white, minority groups would automatically support Nora because of her fight against racism in housing accommodations. If Nora is convicted of trespass by an all-white jury and appeals, claiming a violation of her constitutional rights, the court should', 'affirm the conviction, because Nora was not a member of the class discriminated against.', 'affirm the conviction, because peremptory challenge of the nonwhites did not deny Nora the right to an impartial jury.', 'reverse the conviction, because racially based peremptory challenges violate equal protection of the law.', 'reverse the conviction, because Nora was denied the right to have her case heard by a fair cross section of the community.', 'C', 'In this case, petitioner alleges race discrimination in the prosecution''s use of peremptory challenges.  Invoking the Equal Protection Clause and federal statutory law, and relying upon well-established principles of standing, we hold that a criminal defendant may object to race-based exclusions of jurors effected through peremptory challenges whether or not the defendant and the excluded juror share the same races.', 'mbe_2709', 0, '47'),
('mbe_1073', 'mbe', '1073', '817', '1998', 'CONST. LAW', '79', '', 'A federal statute provides that the cities in which certain specified airports are located may regulate the rates and services of all limousines that serve those airports, without regard to the origin or destination of the passengers who use the limousines. The cities of Redville and Greenville are located adjacent to each other in different states. The airport serving both of them is located in Redville and is one of those airports specified in the federal statute. The Redville City Council has adopted a rule that requires any limousines serving the airport to charge only the rates authorized by the Redville City Council. Airline Limousine Service has a lucrative business transporting passengers between Greenville and the airport in Redville, at much lower rates than those required by the Redville City Council. It transports passengers in interstate traffic only; it does not provide local service within Redville. The new rule adopted by the Redville City Council will require Airline Limousine Service to charge the same rates as limousines operating only in Redville. Must Airline Limousine Service comply with the new rule of the Redville City Council?', 'Yes, because the airport is located in Redville and, therefore, its city council has exclusive regulatory authority over all transportation to and from the airport.', 'Yes, because Congress has authorized this form of regulation by Redville and, therefore, removed any constitutional impediments to it that may have otherwise existed.', 'No, because the rule would arbitrarily destroy a lucrative existing business and, therefore, would amount to a taking without just compensation.', 'No, because Airline Limousine Service is engaged in interstate commerce and this rule is an undue burden on that commerce.', 'B', 'Nor do we know of any reason why Congress may not, if it deems it in the national interest, authorize the states to place similar restraints on movement of articles of commerce. And the provisions looking to state cooperation may be sufficient to warrant the state in imposing regulations approved by the federal authorities, even if they otherwise might run counter to the decisions that coincidence is as fatal as conflict when Congress acts. See Bethlehem Steel Co. v. New York State Labor Relations Board, 330 U.S. 767, 67 S.Ct. 1026, 91 L.Ed. 1234. It is, of course, a quite different thing if Congress through its agents find such restrictions upon interstate commerce advance the national welfare, than if a locality is held free to impose them because it, judging its own cause, finds them in the interest of local prosperity.', 'mbe_2710', 0, '79'),
('mbe_1091', 'mbe', '1091', '834', '1998', 'REAL PROP.', '97', '', 'Olive owned Blackacre, a single-family residence. Fifteen years ago, Olive conveyed a life estate in Blackacre to Lois. Fourteen years ago, Lois, who had taken possession of Blackacre, leased Blackacre to Trent for a term of 15 years at the monthly rental of $500. Eleven years ago, Lois died intestate leaving Ron as her sole heir. Trent regularly paid rent to Lois and, after Lois''s death, to Ron until last month. The period in which to acquire title by adverse possession in the jurisdiction is 10 years. In an appropriate action, Trent, Olive, and Ron each asserted ownership of Blackacre. The court should hold that title in fee simple is in', 'Olive, because Olive held a reversion and Lois has died.', 'Ron, because Lois asserted a claim adverse to Olive when Lois executed a lease to Trent.', 'Ron, because Trent''s occupation was attributable to Ron, and Lois died 11 years ago.', 'Trent, because of Trent''s physical occupancy and because Trent''s term ended with Lois''s death.', 'C', '(“[I]t is one of the essential properties of a lease that its duration shall be for a determinate period, shorter than the duration of the estate of the lessor, hence the estate demised is called a ‘term’, and necessarily implies a reversion. If the entire interest of the lessor is conveyed, in the whole or a portion of his land, the conveyance cannot therefore be properly regarded as a demise ...”).', 'mbe_2711', 0, '97'),
('mbe_1096', 'mbe', '1096', '838', '1998', 'EVIDENCE', '102', '', 'Plaintiff sued Defendant for injuries suffered in a car accident allegedly caused by brakes that had been negligently repaired by Defendant. At a settlement conference, Plaintiff exhibited the brake shoe that caused the accident and pointed out the alleged defect to an expert, whom Defendant had brought to the conference. No settlement was reached. At trial, the brake shoe having disappeared, Plaintiff seeks to testify concerning the condition of the shoe. Plaintiff''s testimony is', 'admissible, because Defendant''s expert had been able to examine the shoe carefully.', 'admissible, because Plaintiff had personal knowledge of the shoe''s condition.', 'inadmissible, because the brake shoe was produced and examined as a part of settlement negotiations.', 'inadmissible, unless Plaintiff establishes that the disappearance was not his fault.', 'B', '“Personal knowledge,” as required for lay witness testimony to be admissible, is a present recollection of an impression derived from the exercise of the witness''s own senses. Cal. Evid. Code § 702(a).', 'mbe_2712', 0, '102'),
('mbe_1097', 'mbe', '1097', '839', '1998', 'CONTRACTS', '103', '', 'Which of the following statements is correct?', 'Fixtures must tender 25 sets to Apartments at Apartments'' place of business on March 1, but does not have to turn them over to Apartments until Apartments pays the contract price for the 25 sets.', 'Fixtures has no duty to deliver the 25 sets on March 1 at Fixtures'' place of business unless Apartments tenders the contract price for the 25 sets on that date.', 'Fixtures must deliver 25 sets on March 1, and Apartments must pay the contract price for the 25 sets within a reasonable time after their delivery.', 'Fixtures must deliver 25 sets on March 1, but Apartments'' payment is due only upon the delivery of all 50 sets.', 'B', 'To constitute a valid tender under an executory contract for the sale of chattels, the law only requires such acts as are practicable according to he character of the thing tendered and the nature of the business; if the articles are ponderous and bulky, a manual delivery is unnecessary.', 'mbe_2713', 0, '103'),
('mbe_1120', 'mbe', '1120', '862', '1998', 'CONST. LAW', '127', '', 'Agitator, a baseball fan, has a fierce temper and an extremely loud voice. Attending a baseball game in which a number of calls went against the home team, Agitator repeatedly stood up, brandished his fist, and angrily shouted, "Kill the umpires." The fourth time he engaged in this conduct, many other spectators followed Agitator in rising from their seats, brandishing fists, and shouting, "Kill the umpires." The home team lost the game. Although no violence ensued, spectators crowded menacingly around the umpires after the game. As a result, the umpires were able to leave the field and stadium only with the help of a massive police escort. For his conduct, Agitator was charged with inciting to riot and was convicted in a jury trial in state court. He appealed. The state supreme court reversed his conviction. In its opinion, the court discussed in detail decisions of the United States Supreme Court dealing with the First Amendment free speech clause as incorporated into the Fourteenth Amendment. At the end of that discussion, however, the court stated that it "need not resolve how, on the basis of these cases," the United States Supreme Court would decide Agitator''s case. "Instead," the court stated, "this court has always given the free-speech guarantee of the state''s constitution the broadest possible interpretation. As a result, we hold that in this case, where no riot or other violence actually occurred, the state constitution does not permit this conviction for incitement to riot to stand." The United States Supreme Court grants a writ of certiorari to review this decision of the state supreme court. In this case, the United States Supreme Court should', 'affirm the state supreme court''s decision, because Agitator''s ballpark shout is commonplace hyperbole that cannot, consistently with the First and Fourteenth Amendments, be punished.', 'remand the case to the state supreme court with directions that it resolve the First and Fourteenth Amendment free- speech issue that it discussed in such detail.', 'dismiss the writ as improvidently granted, because the state supreme court''s decision rests on an independent and adequate state law ground.', 'reverse the decision of the state supreme court, because incitement to violent action is not speech protected by the First and Fourteenth Amendments.', 'C', '. . . [T]he Court will not consider a federal law issue on direct review from a state-court judgment if that judgment rests on a state-law ground that is both “independent” of the federal claim''s merits and an “adequate” basis for the court''s decision.', 'mbe_2714', 0, '127'),
('mbe_1126', 'mbe', '1126', '867', '1998', 'CRIM. LAW', '133', '', 'Sam decided to kill his boss, Anna, after she told him that he would be fired if his work did not improve. Sam knew Anna was scheduled to go on a business trip on Monday morning. On Sunday morning, Sam went to the company parking garage and put a bomb in the company car that Anna usually drove. The bomb was wired to go off when the car engine started. Sam then left town. At 5 a.m. Monday, Sam, after driving all night, was overcome with remorse and had a change of heart. He called the security officer on duty at the company and told him about the bomb. The security officer said he would take care of the matter. An hour later, the officer put a note on Anna''s desk telling her of the message. He then looked at the car but could not see any signs of a bomb. He printed a sign saying "DO NOT USE THIS CAR," put it on the windshield, and went to call the police. Before the police arrived, Lois, a company vice president, got into the car and started the engine. The bomb went off, killing her. The jurisdiction defines murder in the first degree as any homicide committed with premeditation and deliberation or any murder in the commission of a common-law felony. Second-degree murder is defined as all other murder at common law. Manslaughter is defined by the common law. Sam is guilty of', 'murder in the first degree, because, with premeditation and deliberation, he killed whoever would start the car.', 'murder in the second degree, because he had no intention of killing Lois.', 'manslaughter, because at the time of the explosion, he had no intent to kill, and the death of Lois was in part the fault of the security officer.', 'only attempted murder of Anna, because the death of Lois was the result of the security officer''s negligence.', 'A', 'To frame this issue, we begin with K.S.A. 2015 Supp. 21–5402(a), which defines murder in the first degree as “the killing of a human being committed: (1) Intentionally, and with premeditation.” The jury was properly instructed that to prove premeditation the State had to show Seba had “thought the matter over beforehand, in other words, [had] formed the design or intent to kill before the act.” See PIK Crim. 4th 54.150(d) (2013 Supp.). The State relied on the transferred intent doctrine to prove Seba acted intentionally and with premeditation.
This court has previously explained the transferred intent doctrine by stating:
“The fact that the homicidal act was directed against one other than the person killed does not relieve the slayer of criminal responsibility. It is generally held that such a homicide partakes of the quality of the original act, so that the guilt of the perpetrator of the crime is exactly what it would have been had the assault followed upon the intended victim instead of another.” State v. Moffitt, 199 Kan. 514, 535, 431 P.2d 879 (1967), overruled on other grounds by State v. Underwood, 228 Kan. 294, 306, 615 P.2d 153 (1980).
More plainly stated, “ ‘ “the malice or intent follows the bullet.” 40 Am. Jur. 2d, Homicide § 11, pp. 302–03.’ ” State v. Jones, 257 Kan. 856, 860, 896 P.2d 1077 (1995); see State v. Garza, 259 Kan. 826, 829, 916 P.2d 9 (1996) (same).', 'mbe_2715', 0, '133'),
('mbe_1128', 'mbe', '1128', '869', '1998', 'TORTS', '135', '', 'Orderly, a male attendant who worked at Hospital, had sexual relations with Patient, a severely retarded person, in her room at Hospital. In a tort action brought on Patient''s behalf against Hospital, Patient will', 'not prevail, if Orderly''s actions were outside the scope of his employment.', 'not prevail, if Patient initiated the relationship with Orderly and encouraged his actions.', 'prevail, if Orderly was an employee of Hospital.', 'prevail, if Hospital failed to use reasonable care to protect Patient from such conduct.', 'D', 'The Kansas Supreme Court reversed and remanded for many of the same reasons stated in the Washington decision. The provisions of Restatement (Second) of Torts §§ 315, 319 and 320 (1977), were deemed applicable, and the discretionary function exception of the KTCA was held not to be applicable. The court stated the following general principles:
“One who is required by law to take custody of another under circumstances which deprive that person of the normal opportunities for protection is under a duty to protect the person taken into custody against unreasonable risk of physical harm from others.”
 “One who takes charge of a third person whom he knows or should know to be likely to cause bodily harm to others if not controlled is under a duty to exercise reasonable care to control the third person to prevent him from doing such harm.” “One who is required by law to take or who voluntarily takes custody of another under circumstances such as to deprive the other of his normal power of self-protection or to subject him to association with persons likely to harm him is under a duty to exercise reasonable care so to control the conduct of third persons to prevent them from intentionally harming the other or so conducting themselves as to create an unreasonable risk of harm to him, if the actor (a) knows or has reason to know that he has the ability to control the conduct of the third persons and (b) knows or should know of the necessity and opportunity for exercising such control.”', 'mbe_2716', 0, '135'),
('mbe_1134', 'mbe', '1134', '874', '1998', 'CONST. LAW', '141', '', 'The King City zoning ordinance contains provisions restricting places of "adult entertainment" to two specified city blocks within the commercial center of the city. These provisions of the ordinance define "adult entertainment" as "live or filmed nudity or sexual activity, real or simulated, of an indecent nature." Sam proposes to operate an adult entertainment establishment outside the two- block area zoned for such establishments but within the commercial center of King City. When his application for permission to do so is rejected solely because it is inconsistent with provisions of the zoning ordinance, he sues the appropriate officials of King City, seeking to enjoin them from enforcing the adult entertainment provisions of the ordinance against him. He asserts that these provisions of the ordinance violate the First Amendment as made applicable to King City by the Fourteenth Amendment. In this case, the court hearing Sam''s request for an injunction would probably hold that the adult entertainment provisions of the King City zoning ordinance are', 'constitutional, because they do not prohibit adult entertainment everywhere in King City, and the city has a substantial interest in keeping the major part of its commercial center free of uses it considers harmful to that area.', 'constitutional, because adult entertainment of the kind described in these provisions of the King City ordinance is not protected by the free speech guarantee of the First and Fourteenth Amendments.', 'unconstitutional, because they prohibit in the commercial area of the city adult entertainment that is not "obscene" within the meaning of the First and Fourteenth Amendments.', 'unconstitutional, because zoning ordinances that restrict freedom of speech may be justified only by a substantial interest in preserving the quality of a community''s residential neighborhoods.', 'A', 'A regulation is content neutral if it applies regardless of the speech''s message. Content-neutral regulations are reviewed under intermediate scrutiny, which is easier to satisfy than strict scrutiny.
Intermediate scrutiny allows reasonable and content-neutral time, place, or manner regulations (Lebron v. Nat''l R.R. Passenger Corp. (Amtrak), 69 F.3d 650, 655 (2d Cir. 1995)). Under intermediate scrutiny, the government must prove that:
It has a significant governmental interest.
The regulation is narrowly tailored to serve the significant interest. The tailoring does not need to be the least restrictive nor the least intrusive possible.
The regulation leaves open ample alternatives for communication.', 'mbe_2717', 0, '141'),
('mbe_1141', 'mbe', '1141', '881', '1998', 'CONST. LAW', '148', '', 'John is a licensed barber in State A. The State A barber licensing statute provides that the Barber Licensing Board may revoke a barber license if it finds that a licensee has used his or her business premises for an illegal purpose. John was arrested by federal narcotics enforcement agents on a charge of selling cocaine in his barbershop in violation of federal laws. However, the local United States Attorney declined to prosecute and the charges were dropped. Nevertheless, the Barber Licensing Board commenced a proceeding against John to revoke his license on the ground that John used his business premises for illegal sales of cocaine. At a subsequent hearing before the board, the only evidence against John was affidavits by unnamed informants, who were not present or available for cross-examination. Their affidavits stated that they purchased cocaine from John in his barbershop. Based solely on this evidence, the board found that John used his business premises for an illegal purpose and ordered his license revoked. In a suit by John to have this revocation set aside, his best constitutional argument is that', 'John''s inability to cross-examine his accusers denied him a fair hearing and caused him to be deprived of his barber license without due process of law.', 'the administrative license revocation proceeding was invalid, because it denied full faith and credit to the dismissal of the criminal charges by the United States Attorney.', 'Article III requires a penalty of the kind imposed on John to be imposed by a court rather than an administrative agency.', 'the existence of federal laws penalizing the illegal sale of cocaine preempts state action relating to drug trafficking of the kind involved in John''s case.', 'A', 'This Court consistently has held that some form of hearing is required before an individual is finally deprived of a property interest. Wolff v. McDonnell, 418 U.S. 539, 557-558, 94 S.Ct. 2963, 2975-2976, 41 L.Ed.2d 935 (1974). See, e. g. Phillips v. Commissioner of Internal Revenue, 283 U.S. 589, 596-597, 51 S.Ct. 608, 611-612, 75 L.Ed. 1289 (1931). See also Dent v. West Virginia, 129 U.S. 114, 124-125, 9 S.Ct. 231, 234, 32 L.Ed. 623 (1889). The “right to be heard before being condemned to suffer grievous loss of any kind, even though it may not involve the stigma and hardships of a criminal conviction, is a principle basic to our society.” Joint Anti-Fascist Comm. v. McGrath, 341 U.S. 123, 168, 71 S.Ct. 624, 646, 95 L.Ed. 817 (1951) (Frankfurter, J., concurring). The fundamental requirement of due process is the opportunity to be heard “at a meaningful time and in a meaningful manner.” Armstrong v. Manzo, 380 U.S. 545, 552, 85 S.Ct. 1187, 1191, 14 L.Ed.2d 62 (1965). See Grannis v. Ordean, 234 U.S. 385, 394, 34 S.Ct. 779, 783, 58 L.Ed. 1363 (1914).

These decisions underscore the truism that “ ‘(d)ue process,’ unlike some legal rules, is not a technical conception with a fixed content unrelated to time, place and circumstances.” Cafeteria Workers v. McElroy, 367 U.S. 886, 895, 81 S.Ct. 1743, 1748, 6 L.Ed.2d 1230 (1961).  “(D)ue process is flexible and calls for such procedural protections as the particular situation demands.” Morrissey v. Brewer, 408 U.S. 471, 481, 92 S.Ct. 2593, 2600, 33 L.Ed.2d 484 (1972). Accordingly, resolution of the issue whether the administrative procedures provided here are constitutionally sufficient requires analysis of the governmental and private interests that are affected. Arnett v. Kennedy, supra, 416 U.S., at 167-168, 94 S.Ct., at 1650-1651 (Powell, J., concurring in part); Goldberg v. Kelly, supra, 397 U.S., at 263-266, 90 S.Ct., at 1018-1020; **903 Cafeteria Workers v. McElroy, supra, 367 U.S., at 895, 81 S.Ct., at 1748-1749. More precisely, our prior decisions *335 indicate that identification of the specific dictates of due process generally requires consideration of three distinct factors: First, the private interest that will be affected by the official action; second, the risk of an erroneous deprivation of such interest through the procedures used, and the probable value, if any, of additional or substitute procedural safeguards; and finally, the Government''s interest, including the function involved and the fiscal and administrative burdens that the additional or substitute procedural requirement would entail. See, e. g., Goldberg v. Kelly, supra, 397 U.S., at 263-271, 90 S.Ct., at 1018-1022.', 'mbe_2718', 0, '148'),
('mbe_1149', 'mbe', '1149', '889', '1998', 'CONTRACTS', '156', '', 'For this question only, assume that Computers tendered the computer to Bank on August 15, and that Bank rejected it because of the delay. If Computers sues Bank for breach of contract, which of the following facts, if proved, will best support a recovery by Computers?', 'The delay did not materially harm Bank.', 'Computers believed, on the assumption that Bank was getting a "super deal" for its money, that Bank would not reject because of the late tender of delivery.', 'Computers'' delay in tender was caused by a truckers'' strike.', 'A usage in the relevant trade allows computer sellers a 30-day leeway in a specified time of delivery, unless the usage is expressly negated by the contract.', 'D', '“The express terms of an agreement and an applicable course of dealing or usage of trade shall be construed wherever reasonable as consistent with each other; but when such construction is unreasonable express terms control both course of dealing and usage of trade and course of dealing controls usage of trade.” Id. s 490:1-205(4).', 'mbe_2719', 0, '156'),
('mbe_1172', 'mbe', '1172', '912', '1998', 'EVIDENCE', '179', '', 'Defendant is on trial for participating in a drug sale. The prosecution calls Witness, an undercover officer, to testify that, when Seller sold the drugs to Witness, Seller introduced Defendant to Witness as "my partner in this" and Defendant shook hands with Witness but said nothing. Witness''s testimony is', 'inadmissible, because there is no evidence that Seller was authorized to speak for Defendant.', 'inadmissible, because the statement of Seller is hearsay not within any exception.', 'admissible as a statement against Defendant''s penal interest.', 'admissible as Defendant''s adoption of Seller''s statement.', 'D', 'An adoptive admission is one “made in the presence of the defendant to which the defendant''s response—whether by oral declaration, by gesture, or by revealing silence—objectively denotes the defendant''s acceptance of the statement.” Commonwealth v. Stewart, 450 Mass. 25, 34, 875 N.E.2d 846 (2007), *795 quoting **64 Commonwealth v. Babbitt, 430 Mass. 700, 705, 723 N.E.2d 17 (2000).', 'mbe_2720', 0, '179'),
('mbe_1186', 'mbe', '1186', '926', '1998', 'EVIDENCE', '193', '', 'At Defendant''s trial for sale of drugs, the government called Witness to testify, but Witness refused to answer any questions about Defendant and was held in contempt of court. The government then calls Officer to testify that, when Witness was arrested for possession of drugs and offered leniency if he would identify his source, Witness had named Defendant as his source. The testimony offered concerning Witness''s identification of Defendant is', 'admissible as a prior inconsistent statement by Witness.', 'admissible as an identification of Defendant by Witness after having perceived him.', 'inadmissible, because it is hearsay not within any exception.', 'inadmissible, because Witness was not confronted with the statement while on the stand.', 'C', 'However, prior inconsistent statements by a witness are generally admissible for impeachment purposes. People v. Johnson, 2012 IL App (1st) 091730, ¶ 68, 373 Ill.Dec. 1, 993 N.E.2d 1.', 'mbe_2721', 0, '193'),
('vs_3cdb657d2d37', 'vector_store_generated', 'vs_3cdb657d2d37', 'vs_3cdb657d2d37', 'vector_store_generated', 'Torts', '', 'A plaintiff is injured after slipping on a wet floor in a supermarket. They argue that the store was negligent for not placing a sign warning about the wet floor. The defendant claims that the injury was too indirect and should not hold them liable.', 'In a negligence case, if a defendant''s conduct is found to be the proximate cause of a plaintiff''s injuries, which of the following is valid regarding the defendant''s liability?', 'The defendant is not liable because the injury was not a foreseeable result of their actions.', 'The defendant is liable if it is established that their conduct created a foreseeable risk of harm.', 'The defendant is liable only if the plaintiff can show that their injuries were intentional.', 'The defendant is not liable if the plaintiff was partially at fault for the injury.', 'B', 'A defendant can be liable for negligence if their conduct was the proximate cause of the injury and the injury was a foreseeable result of that conduct.', 'vs_3cdb657d2d37', 0, NULL),
('vs_c28ddb92a3a1', 'vector_store_generated', 'vs_c28ddb92a3a1', 'vs_c28ddb92a3a1', 'vector_store_generated', 'Contracts', '', 'Emily promises to sell her bike to John for $100. John promises to pay Emily when he receives the bike. What type of contract is this and what must occur for the contract to be enforceable?', 'Which of the following statements about a bilateral contract is true?', 'This is a unilateral contract that requires performance from either party for enforceability.', 'This is a bilateral contract that requires an exchange of promises to be enforceable.', 'This is a voidable contract that can be rescinded at any time by either party.', 'This is a bilateral contract that requires one party to perform before the agreement becomes binding.', 'B', 'A bilateral contract involves an exchange of promises and is enforceable as soon as the promises are made, not requiring performance.', 'vs_c28ddb92a3a1', 0, NULL),
('vs_fdf9ccde0a99', 'vector_store_generated', 'vs_fdf9ccde0a99', 'vs_fdf9ccde0a99', 'vector_store_generated', 'Criminal Law', '', 'Tom enters a store with the intention to commit theft. However, once inside, he changes his mind and does not steal anything. What does this mean for the charge of burglary?', 'In a criminal law context, which of the following correctly describes the ''mens rea'' requirement in California burglary statutes?', 'Tom can be charged with burglary if he had the intent to commit theft at the time of entry.', 'Tom cannot be charged because he did not complete the act of theft.', 'Tom can only be charged if he left the store with stolen property.', 'Tom cannot be charged unless the store owner pressed charges.', 'A', 'Under California law, the intent to commit a crime at the time of entry constitutes sufficient mens rea for burglary, regardless of whether the crime was completed.', 'vs_fdf9ccde0a99', 0, NULL),
('vs_090ec5c2b1f7', 'vector_store_generated', 'vs_090ec5c2b1f7', 'vs_090ec5c2b1f7', 'vector_store_generated', 'Civil Procedure', '', 'CompuChip, a Japanese corporation, sold a ''special'' microchip illegal under California law directly to a friend of a California resident, who then used it in a motorcycle assembly leading to an injury. CompuChip moves to dismiss the case against it.', 'When determining whether a California court has personal jurisdiction over a foreign corporation, what must the court primarily consider?', 'Whether CompuChip purposefully availed itself of the California market.', 'Whether the injury occurred in Japan where CompuChip is based.', 'Whether the plaintiff was a California resident.', 'Whether California law recognizes the sale of illegal goods.', 'A', 'The court must analyze whether CompuChip purposefully availed itself of the privilege of conducting activities within California, establishing enough contacts to support personal jurisdiction .', 'vs_090ec5c2b1f7', 0, NULL),
('vs_727d70f2bc3d', 'vector_store_generated', 'vs_727d70f2bc3d', 'vs_727d70f2bc3d', 'vector_store_generated', 'Contracts', '', 'Martha agreed to sell and deliver custom bicycles to a local shop in California. Upon delivery, the bicycles were found defective. The shop paid for the bicycles but later sought a refund due to the defects. Martha claims she should not have to refund the payment based on an oral agreement before the contract that was not documented.', 'In a breach of contract case involving the sale of goods, which of the following defenses is most likely applicable for a seller seeking to avoid payment due for damages caused by defective goods?', 'The Statute of Frauds prevents enforcing the oral agreement.', 'The warranty of merchantability is not applicable.', 'Specific performance is the only remedy available.', 'The shop accepted the goods and therefore cannot seek damages.', 'A', 'The Statute of Frauds requires certain contracts to be in writing to be enforceable; Martha''s claim regarding an oral agreement without written documentation is a valid defense .', 'vs_727d70f2bc3d', 0, NULL),
('civ0001', 'workshop_civpro', 'civ0001', 'civ0001', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '1', 'A corporation filed a breach of contract action against another corporation in the United States District Court for the District of State A on the basis of diversity of citizenship jurisdiction. The action seeks $80,000 in damages. The plaintiff corporation was incorporated in State B and has its principal place of business in State C. The defendant corporation was incorporated in State C and has its principal place of business in State A. The defendant corporation filed a motion to dismiss the action for lack of subject matter jurisdiction. Will the defendant corporation’s motion be granted?', 'Yes, because both corporations are citizens of State C.', 'Yes, because the defendant corporation is a citizen of the state in which the action was filed.', 'No, because the plaintiff corporation is a citizen of State C and the defendant corporation is a citizen of State A.', 'No, because, while both corporations are citizens of State C, the plaintiff corporation is also a citizen of State B and the defendant corporation is also a citizen of State A.', 'D', '', 'civ0001', 0, NULL)
ON CONFLICT (idx) DO NOTHING;
